#!/usr/bin/env node
/*
 * Embeds the Tier-2 offline widget into a TypeScript module (OR-475 / design §5H).
 *
 * The vendored bundle (from `mesh-backup-widget`, OR-472 + OR-473) is:
 *   - widget.offline.html   — self-contained offline build (Phase 6b). The Phase 6a
 *                             catalog snapshot + top-N logos are ALREADY inlined
 *                             into this file at the widget's build time, so it is
 *                             the ONLY asset the SDK loads at runtime (into an
 *                             iframe via `srcdoc`).
 *   - catalog.snapshot.json — kept alongside for drift diffing + the size guard
 *                             (`check-bundle-size.js`); NOT loaded at runtime (its
 *                             contents already live inside widget.offline.html).
 *
 * A library built with `tsc` cannot import a raw .html file as a string, so this
 * script projects widget.offline.html into src/backup-bundle/generated.ts, which
 * the SDK imports (dynamically, so Tier-1-only consumers can code-split it out).
 * On every SDK release the two files are re-vendored from mesh-backup-widget (the
 * Phase 6a/6b outputs); re-run `pnpm bundle:embed` and commit the result. The
 * generated file is committed so `pnpm test` / typecheck work without a pre-step;
 * `pnpm bundle:check` fails CI if the committed module is stale.
 */
import fs from 'fs'
import path from 'path'
import { fileURLToPath, pathToFileURL } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

const bundleDir = path.resolve(__dirname, '../src/backup-bundle')
export const HTML_PATH = path.join(bundleDir, 'widget.offline.html')
export const SNAPSHOT_PATH = path.join(bundleDir, 'catalog.snapshot.json')
export const OUT_PATH = path.join(bundleDir, 'generated.ts')

/** Size of the shipped HTML in the UTF-8 bytes that actually go over the wire —
 *  NOT `String.length` (UTF-16 code units), which undercounts non-ASCII. */
export const htmlByteLength = html => Buffer.byteLength(html, 'utf8')

/**
 * Fail if the "offline" HTML references anything it would fetch over the network,
 * so the bundled Tier-2 asset truly makes no network calls. Covers the
 * resource-loading mechanisms a naive `src=/href=https?:` check misses: `srcset`,
 * `xlink:href`, CSS `url(...)`, `@import`, and protocol-relative (`//`) forms.
 *
 * Deliberately NOT flagged: `xmlns="http://www.w3.org/..."` and other XML/SVG
 * namespace declarations — those are identifiers, not network loads (the attribute
 * name is `xmlns`, which is not in the resource-attribute list below). Everything
 * legitimate in a self-contained build uses `data:` URIs or inline content.
 *
 * Single source of truth: `generate()` calls this, and `check-bundle-size.js`
 * relies on `generate()`, so `bundle:embed` can never emit a network-dependent
 * module and CI can never pass one.
 */
export function assertSelfContained(html) {
  const checks = [
    [
      /\b(?:src|srcset|href|xlink:href)\s*=\s*["'`]?\s*(?:https?:)?\/\//i,
      'an external src/srcset/href/xlink:href'
    ],
    [
      /@import\s+(?:url\(\s*)?["'`]?\s*(?:https?:)?\/\//i,
      'a CSS @import of an external URL'
    ],
    [/url\(\s*["'`]?\s*(?:https?:)?\/\//i, 'a CSS url() of an external URL']
  ]
  for (const [re, what] of checks) {
    if (re.test(html)) {
      throw new Error(
        `widget.offline.html is not self-contained — found ${what}. ` +
          'A Tier-2 offline bundle must reference no network resources.'
      )
    }
  }
}

/** Build the generated.ts content from the vendored offline widget. */
export function generate() {
  if (!fs.existsSync(HTML_PATH)) throw new Error(`missing ${HTML_PATH}`)

  const html = fs.readFileSync(HTML_PATH, 'utf8')
  if (!/<!doctype html>/i.test(html)) {
    throw new Error('widget.offline.html does not look like an HTML document')
  }
  assertSelfContained(html)

  // JSON.stringify(html) yields a valid, fully-escaped double-quoted JS string
  // literal (quotes, backslashes, newlines handled).
  const content = `/* eslint-disable */
// AUTO-GENERATED by tools/embed-backup-bundle.js — DO NOT EDIT BY HAND.
// Source: src/backup-bundle/widget.offline.html (vendored from mesh-backup-widget,
// OR-472 + OR-473). The catalog snapshot + top-N logos are already inlined in that
// HTML. Regenerate with \`pnpm bundle:embed\`; \`pnpm bundle:check\` verifies sync.

/** Self-contained Tier-2 offline widget, loaded into an iframe via \`srcdoc\`. */
export const OFFLINE_WIDGET_HTML: string = ${JSON.stringify(html)}
`

  return { content, html }
}

// Run directly (not imported): write the file. Compare as file URLs so paths with
// spaces / on Windows still match (a manual `file://` + path prefix would not).
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  let result
  try {
    result = generate()
  } catch (e) {
    console.error(`embed-backup-bundle: ${e.message} ❌`)
    process.exit(1)
  }
  fs.writeFileSync(OUT_PATH, result.content)
  console.log(
    `embed-backup-bundle: wrote ${path.relative(process.cwd(), OUT_PATH)} ` +
      `(${(htmlByteLength(result.html) / 1024).toFixed(1)} KB html) ✅`
  )
}
